import{_ as a,a as e}from"./chunks/08-model-settings.wwAq27Vh.js";import{_ as r}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as o,o as i,c as n,a2 as d}from"./chunks/framework.z3u3TMv0.js";const f=JSON.parse('{"title":"モデル接続とパラメータ","description":"MiniTavern BYOK モデル接続：Base URL と API Key、測連、サンプリング；クラウドまたは Ollama/LM Studio のローカル OpenAI 互換へ接続。","frontmatter":{"title":"モデル接続とパラメータ","description":"MiniTavern BYOK モデル接続：Base URL と API Key、測連、サンプリング；クラウドまたは Ollama/LM Studio のローカル OpenAI 互換へ接続。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"モデル接続とパラメータ · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK モデル接続：Base URL と API Key、測連、サンプリング；クラウドまたは Ollama/LM Studio のローカル OpenAI 互換へ接続。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/manual/model-link"}]]},"headers":[],"relativePath":"ja/manual/model-link.md","filePath":"ja/manual/model-link.md","lastUpdated":1787224147000}'),l={name:"ja/manual/model-link.md"};function s(p,t,h,u,c,m){return i(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="モデル接続とパラメータ" tabindex="-1">モデル接続とパラメータ <a class="header-anchor" href="#モデル接続とパラメータ" aria-label="Permalink to &quot;モデル接続とパラメータ&quot;">​</a></h1><p>BYOK：鍵は端末の安全領域に保存；リクエストは設定したアドレスへ直結します。</p><p>有料 API がないときは先に <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>；本機配備は <a href="/ultra_guides/ja/local/">ローカルモデル</a>。</p><h2 id="モデル接続" tabindex="-1">モデル接続 <a class="header-anchor" href="#モデル接続" aria-label="Permalink to &quot;モデル接続&quot;">​</a></h2><p>経路：<strong>設定 → モデル → モデル接続</strong></p><p><img src="'+a+'" alt="モデル接続一覧"></p><table tabindex="0"><thead><tr><th>操作</th><th>説明</th></tr></thead><tbody><tr><td>新規</td><td>プラットフォーム、鍵、Base URL、モデル</td></tr><tr><td>編集 / 複製 / 削除</td><td>一覧右のメニュー</td></tr><tr><td>デフォルトに設定</td><td>新規対話の既定</td></tr><tr><td>測連</td><td>保存前または編集ページの「テスト」。<strong>テキストチャット</strong>モデルを選ぶこと；TTS / 画像専用 ID（例 Gemini <code>*-tts</code>）は文字対話非対応で失敗 → <a href="./errors#textoutputunsupported">エラー排錯 · textOutputUnsupported</a></td></tr></tbody></table><h3 id="プラットフォーム種別-よくあるもの" tabindex="-1">プラットフォーム種別（よくあるもの） <a class="header-anchor" href="#プラットフォーム種別-よくあるもの" aria-label="Permalink to &quot;プラットフォーム種別（よくあるもの）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>選択肢（文案は App 準拠）</th><th>用途</th></tr></thead><tbody><tr><td>各クラウドのプリセット</td><td>国内／国際サイトの Base URL を自動記入</td></tr><tr><td>カスタム (OpenAI プロトコル)</td><td>ローカル Ollama / LM Studio、互換ゲートウェイ</td></tr><tr><td>カスタム Gemini / Anthropic</td><td>対応プロトコルのエンドポイント</td></tr></tbody></table><p>複数サイトのプラットフォームは「国際サイトを使う」に切り替え可。ローカルは <a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern 設定</a> と <a href="/ultra_guides/ja/local/tools">ツール一覧</a>。</p><p><img src="'+r+'" alt="接続の新規作成"></p><h2 id="モデル設定-グローバルパラメータ" tabindex="-1">モデル設定（グローバルパラメータ） <a class="header-anchor" href="#モデル設定-グローバルパラメータ" aria-label="Permalink to &quot;モデル設定（グローバルパラメータ）&quot;">​</a></h2><p>経路：<strong>設定 → モデル設定</strong></p><p><img src="'+e+'" alt="モデル設定"></p><p>よくある項目（名称は App 準拠）：</p><ul><li>記憶の長さ（履歴件数関連）</li><li>返信トークン（max tokens、上限 128000；一部 Claude では <strong>None にしない</strong>）</li><li>Temperature、Top-P / Top-K</li><li>ストリーミング出力の有無</li></ul><h2 id="セッション単位の上書き" tabindex="-1">セッション単位の上書き <a class="header-anchor" href="#セッション単位の上書き" aria-label="Permalink to &quot;セッション単位の上書き&quot;">​</a></h2><p>経路：対話ページ → <strong>設定</strong> → モデル接続 / パラメータ</p><p>単聊ごとに接続とサンプリングを指定でき、グローバル既定は変えません。</p><h2 id="チャット設定の画像認識" tabindex="-1">チャット設定の画像認識 <a class="header-anchor" href="#チャット設定の画像認識" aria-label="Permalink to &quot;チャット設定の画像認識&quot;">​</a></h2><p>経路：<strong>設定 → チャット → 画像認識設定</strong></p><p>単聊はチャット設定 → <strong>画像認識と表示</strong> で既定に従うか個別上書き（描写モデルとプロンプトはグローバルのまま）。</p><ul><li>「画像描写」をオフ：マルチモーダルで画像をそのままモデルへ（視覚対応が必要）。</li><li>オン：現在の主チャットモデルが<strong>画像パラメータ非対応</strong>のときだけ有効——先に描写モデルで図→文（人物認識と同一リクエスト可）、その後主モデルへ；描写結果はキャッシュ再利用。主モデルが視覚対応なら引き続きマルチモーダル直送し、このスイッチは遮断しません。</li></ul><p>画像非対応の主モデル＋描写オン時の送信順：描写（＋人物認識）→ 主チャット（スマート／キーワード返信出図が有効なら画像プロンプトを付帯）→ 返信に画像データがあればバイパスで画像生成。</p><p>「現在のモデルは画像に非対応」と出たら <a href="./errors#visionunsupported">エラー排錯 · visionUnsupported</a>。</p><h2 id="画像生成-接続-返信画像-キーワード" tabindex="-1">画像生成（接続 / 返信画像 / キーワード） <a class="header-anchor" href="#画像生成-接続-返信画像-キーワード" aria-label="Permalink to &quot;画像生成（接続 / 返信画像 / キーワード）&quot;">​</a></h2><p>経路：<strong>設定 → 画像生成</strong></p><ul><li><strong>画像接続 / 画像設定</strong>：API、サイズ／品質、生成枚数（<code>/imagine</code> のみ）、強化／ネガティブプロンプト（<code>/imagine</code> と添付メニューの画像生成のみ；既定の画質語／低品質・ぼかし・余分な指・透かしなど）</li><li><strong>返信画像</strong>（画像設定内）：先にスイッチをオンし、トリガー方式を選ぶ。オフ後はチャットが自動出図しない（スラッシュコマンド、添付メニュー、長押し吹き出しは影響なし） <ul><li><strong>スマート判定</strong>：モデルがこのラウンドで出図するかを対話から判断；画角は場面に応じる（スマホ自撮り 3:4、カメラ成片 3:2）、ヒット後は固定 1 枚。添付送信可（例「このスタイルで撮って」）、添付はスタイル参考で、キャラ／ユーザー身分図の判定は置き換えない</li><li><strong>キーワードトリガー</strong>：ユーザーメッセージがキーワード規則にヒットしたとき出図（添付可）；画面と画角は現在の対話から生成、ヒット後は固定 1 枚</li></ul></li><li><strong>キーワード触発生図</strong>：規則を設定。実際にトリガーするには、画像設定で返信画像をオンしキーワードトリガーを選ぶこと</li></ul><p>チャット内の画像生成：</p><table tabindex="0"><thead><tr><th>入口</th><th>説明</th></tr></thead><tbody><tr><td><code>/imagine プロンプト</code></td><td>先に主チャットモデルが判定：現在の対話と関係あるか、キャラ／ユーザー参考図が要るか、その後プロンプトを組み立てて生図。先に＋で添付可：主モデルがそれらの図を見てから生図プロンプトを書き、生図時も参考にする；添付があってもキャラ図／ユーザー図の判定はスキップしない。これらの図は生図吹き出しの小プレビューに出るだけで、チャット発言にはならない。枚数は画像設定の「生成枚数」。失敗時は吹き出しが残り再試行できる</td></tr><tr><td><code>/imagine scene</code> / 添付 → 物語に基づく</td><td>直近の対話から今の一幕を描く、1 枚</td></tr><tr><td><code>/imagine last</code> / 添付 → 最後のメッセージに基づく</td><td>最後のメッセージから描く、1 枚</td></tr><tr><td>添付 → 背景図を生成</td><td>環境背景を描く、1 枚；完了後チャット背景に設定可</td></tr><tr><td>長押し吹き出し → 生図</td><td>その吹き出しから描く、1 枚</td></tr></tbody></table><p>画像接続未設定時、添付メニューの四つの生図モードと <code>/imagine</code> 送信は「設定へ / キャンセル」を出し、入力欄は消さない。スマート／キーワード自動出図は Toast。画像設定で「返信画像」をオンするとき接続がなければダイアログ、スイッチはオフのまま。</p><p>例：「自撮りを一枚」→ キャラ参考と対話文脈付き；「子犬の写真を一枚」→ 独立リクエストで描き、キャラの顔は当てはめない。</p><p>本機 A1111 / ComfyUI：<a href="/ultra_guides/ja/local/image-gen/">画像モデル配備</a> · <a href="/ultra_guides/ja/local/image-gen/connect-app">App 接続</a>。<br> クラウド無料帯は <a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料クラウド · 画像生成</a>。</p><h2 id="排錯入口" tabindex="-1">排錯入口 <a class="header-anchor" href="#排錯入口" aria-label="Permalink to &quot;排錯入口&quot;">​</a></h2><p>測連またはチャット失敗 → Toast / 吹き出し → <strong>詳細を見る</strong>（エラーコード＋原因＋提案）→ <a href="./errors">エラーコード排錯</a>。</p>',35)])])}const A=o(l,[["render",s]]);export{f as __pageData,A as default};
